algoritmoVoraz(Candidatos) BEGIN
  CS <- {};
  encontrado <- F;

  WHILE (NOT vacio(Candidatos) AND NOT encontrado) DO BEGIN
    x <- seleccionar(Candidatos);

    IF (factible(x, CS)) THEN BEGIN
      CS <- incluir(x, CS);
    END

    Candidatos <- remover(x, Candidatos);

    IF (esSolucion(CS)) THEN BEGIN
      encontrado <- T;
    END
  END

  RETURN CS;
END

cambioVoraz(D[n], objetivo) BEGIN
  restante <- objetivo;
  CS <- {};

  WHILE (restante > 0) DO BEGIN
    moneda <- seleccionarMayorFactible(D, restante);

    IF (moneda = -1) THEN BEGIN
      RETURN -1;
    END

    CS <- incluir(moneda, CS);
    restante <- restante - moneda;
  END

  RETURN CS;
END

warnsdorff(tablero[n][n], inicio) BEGIN
  actual <- inicio;
  ruta <- {actual};
  marcarVisitada(actual);

  WHILE (longitud(ruta) < n * n) DO BEGIN
    candidatos <- movimientosFactibles(actual, tablero);

    IF (vacio(candidatos)) THEN BEGIN
      RETURN -1;
    END

    siguiente <- candidatoMenorGrado(candidatos, tablero);
    ruta <- incluir(siguiente, ruta);
    marcarVisitada(siguiente);
    actual <- siguiente;
  END

  RETURN ruta;
END

seleccionarActividades(inicio[n], fin[n]) BEGIN
  ordenarPorFin(inicio, fin);
  CS <- {};
  ultimoFin <- 0;

  FOR i <- 1 TO n DO BEGIN
    IF (inicio[i] >= ultimoFin) THEN BEGIN
      CS <- incluir(i, CS);
      ultimoFin <- fin[i];
    END
  END

  RETURN CS;
END

